"""Transactional PostgreSQL loader for artifacts generated by this package."""
from __future__ import annotations

import json
from pathlib import Path

import psycopg
from psycopg.types.json import Jsonb

PRODUCT = ["product_id", "name", "taxonomy", "destination", "description", "attributes", "unit_price", "currency", "available",
           "available_from", "available_to", "image_url", "source_ref"]
PROFILE = ["cdp_user_id", "lifecycle_stage", "days_since_last_booking", "lifetime_order_count", "vinclub_tier", "purchased_verticals",
           "home_city", "last_destination", "email_optin", "sms_optin", "push_optin", "created_at", "updated_at"]
EVENT = ["event_id", "cdp_user_id", "event_name", "timestamp", "product_id", "taxonomy", "event_group_id", "quantity", "unit_price", "using_date"]
COMBO = ["combo_product_id", "position", "label", "item_kind", "item_product_id", "quantity", "unit", "is_optional", "source",
         "confidence", "evidence"]
USER = ["user_id", "email", "password_hash", "display_name", "cdp_user_id", "persona", "created_at", "last_login_at"]
BOOKING = ["booking_id", "reference_code", "cdp_user_id", "event_group_id", "status", "contact_name", "contact_email", "contact_phone",
           "special_request", "total_amount", "currency", "created_at"]
ITEM = ["booking_item_id", "booking_id", "product_id", "taxonomy", "product_name", "unit_price", "quantity", "using_date", "using_date_to",
        "guest_names"]
PARTNER = ["partner_name", "request_token", "created_at"]
IPROFILE = ["profile_id", "partner_name", "attributes", "gdpr_optin", "created_at", "updated_at"]
IDENT = ["identifier_id", "profile_id", "id_type", "id_value", "valid_from", "valid_to"]
IEVENT = ["event_id", "profile_id", "event_name", "event_params", "event_time", "received_at"]
CHANNEL = ["channel_event_id", "profile_id", "channel", "event_type", "campaign_id", "event_time", "metadata"]
JSONB = {"attributes", "event_params", "metadata"}

VOTA_TABLES = (
    ("cdp.products", PRODUCT, "cdp_products.jsonl", "loader"),
    ("catalog.combo_items", COMBO, "catalog_combo_items.jsonl", "loader"),
    ("cdp.profiles", PROFILE, "cdp_profiles.jsonl", "seed"),
    ("cdp.events", EVENT, "cdp_events.jsonl", "seed"),
    ("app.users", USER, "app_users.jsonl", "seed"),
    ("app.bookings", BOOKING, "app_bookings.jsonl", "seed"),
    ("app.booking_items", ITEM, "app_booking_items.jsonl", "seed"),
)
INSIDER_TABLES = (
    ("partners", PARTNER, "insider_partners.jsonl"),
    ("insider_profiles", IPROFILE, "insider_profiles.jsonl"),
    ("identifiers", IDENT, "insider_identifiers.jsonl"),
    ("insider_events", IEVENT, "insider_events.jsonl"),
    ("channel_events", CHANNEL, "insider_channel_events.jsonl"),
)


def read_jsonl(path: Path) -> list[dict]:
    with path.open(encoding="utf-8") as stream:
        return [json.loads(line) for line in stream if line.strip()]


def copy_rows(conn: psycopg.Connection, table: str, columns: list[str], rows: list[dict]) -> int:
    quoted = ", ".join(f'"{column}"' for column in columns)
    with conn.cursor() as cursor, cursor.copy(f"COPY {table} ({quoted}) FROM STDIN") as copy:
        for row in rows:
            copy.write_row([Jsonb(row[column]) if column in JSONB and row[column] is not None else row[column] for column in columns])
    return len(rows)


def _require_empty(conn: psycopg.Connection, tables: tuple[str, ...], reset: bool, database_name: str) -> None:
    occupied = [table for table in tables if conn.execute(f"SELECT EXISTS (SELECT 1 FROM {table} LIMIT 1)").fetchone()[0]]
    if occupied and not reset:
        raise RuntimeError(f"{database_name} already contains seed data in {', '.join(occupied)}; rerun with --reset")


def load_vota(url: str, data_dir: Path, reset: bool) -> dict[str, int]:
    """Load catalog, CDP history and app personas in one transaction."""
    counts: dict[str, int] = {}
    with psycopg.connect(url) as conn:
        _require_empty(conn, tuple(table for table, *_ in VOTA_TABLES), reset, "vota")
        if reset:
            conn.execute("""
                TRUNCATE app.search_logs, app.recommendation_logs, app.itineraries,
                         app.conversation_messages, app.conversations, app.cart_items,
                         app.carts, app.booking_items, app.bookings, app.users,
                         catalog.product_vectors, catalog.combo_items,
                         cdp.events, cdp.profiles, cdp.products
                RESTART IDENTITY CASCADE
            """)
        for table, columns, filename, subdir in VOTA_TABLES:
            rows = read_jsonl(data_dir / subdir / filename)
            counts[table] = copy_rows(conn, table, columns, rows)
        conn.execute("SELECT setval(pg_get_serial_sequence('cdp.events', 'event_id'), COALESCE((SELECT max(event_id) FROM cdp.events), 1))")
        conn.execute("ANALYZE")
    return counts

def load_insider(url: str, data_dir: Path, reset: bool) -> dict[str, int]:
    """Load the separate Insider clone database in one transaction."""
    counts: dict[str, int] = {}
    with psycopg.connect(url) as conn:
        _require_empty(conn, tuple(table for table, *_ in INSIDER_TABLES), reset, "insider")
        if reset:
            conn.execute("TRUNCATE channel_events, insider_events, identifiers, insider_profiles, partners RESTART IDENTITY CASCADE")
        for table, columns, filename in INSIDER_TABLES:
            rows = read_jsonl(data_dir / "seed" / filename)
            counts[f"insider.{table}"] = copy_rows(conn, table, columns, rows)
        for table, column in (("identifiers", "identifier_id"), ("insider_events", "event_id"), ("channel_events", "channel_event_id")):
            conn.execute(f"SELECT setval(pg_get_serial_sequence('{table}', '{column}'), COALESCE((SELECT max({column}) FROM {table}), 1))")
        conn.execute("ANALYZE")
    return counts
